#include <iostream>
#include <vector>
using namespace std;

const int RANGE = 1001;
vector<int> bucket[RANGE];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    for (int i = 0; i < n; i++) {
        int key, id;
        cin >> key >> id;
        bucket[key].push_back(id);   // 按输入顺序追加 → 稳定
    }

    bool first = true;
    for (int k = 0; k < RANGE; k++) {
        for (int id : bucket[k]) {
            if (!first) cout << ' ';
            cout << id;
            first = false;
        }
    }
    cout << "\n";
    return 0;
}
